395	        let (s, e) = (self.0.bounds.end(), self.0.bounds.end() + field.len());
396	        while e > self.0.fields.len() {
397	            self.expand_fields();
398	        }
399	        self.0.fields[s..e].copy_from_slice(field);
400	        self.0.bounds.add(e);
