428	    ///     {
429	    ///         let pos = record.position().expect("a record position");
430	    ///         assert_eq!(pos.byte(), 6);
431	    ///         assert_eq!(pos.line(), 2);
432	    ///         assert_eq!(pos.record(), 1);
