94	fn record_rows(reader: &mut csv_core::Reader, data: &[u8], sizes: &[usize], profile: usize) -> Rows {
95	    assert_eq!(sizes.iter().sum::<usize>(), data.len());
96	    let (mut pos, mut boundary, mut chunk) = (0, 0, 0);
97	    let mut result = Rows::new();
98	    let mut bytes = Vec::new();
99	    let mut ends = Vec::new();
100	    for turn in 0..10000 {
101	        if pos == boundary && chunk < sizes.len() { boundary += sizes[chunk]; chunk += 1; }
102	        let input = &data[pos..boundary];
103	        let supplied = input.len();
104	        let (cap, end_cap) = capacities(profile, turn);
105	        let mut output = vec![0; cap];
106	        let mut positions = vec![0; end_cap];
107	        let (status, nin, nout, nend) = reader.read_record(input, &mut output, &mut positions);
108	        assert!(nin <= supplied, "read_record counted previously received input: {} > {}", nin, supplied);
109	        assert!(nout <= cap && nend <= end_cap, "invalid read_record return counts");
110	        pos += nin;
111	        bytes.extend_from_slice(&output[..nout]);
112	        for &end in &positions[..nend] {
113	            assert!(end >= ends.last().copied().unwrap_or(0), "field ends are not ordered");
114	            assert!(end <= bytes.len(), "field end includes bytes absent from decoded output");
115	            ends.push(end);
116	        }
117	        match status {
118	            R::Record => {
119	                assert!(!ends.is_empty(), "record without a field end");
120	                assert_eq!(ends.last().copied(), Some(bytes.len()));
121	                let mut previous = 0;
122	                let mut decoded = Vec::new();
123	                for &end in &ends { decoded.push(bytes[previous..end].to_vec()); previous = end; }
124	                result.push(decoded);
125	                bytes.clear();
126	                ends.clear();
127	            }
128	            R::End => {
129	                assert_eq!(supplied, 0, "End requires caller-supplied empty input");
130	                assert_eq!(pos, data.len(), "End before consuming the input");
131	                assert!(bytes.is_empty() && ends.is_empty(), "unfinished data at End");
132	                return result;
133	            }
134	            R::InputEmpty | R::OutputFull | R::OutputEndsFull => {}
135	        }
136	    }
137	    panic!("read_record did not finish after restoring buffer space");
138	}
