242	struct Fragmented { cursor: Cursor<Vec<u8>>, sizes: VecDeque<usize>, left: usize }
243	impl Fragmented {
244	    fn new(data: &[u8], sizes: Vec<usize>) -> Self {
245	        Self { cursor: Cursor::new(data.to_vec()), sizes: sizes.into(), left: 0 }
246	    }
247	}
248	impl Read for Fragmented {
249	    fn read(&mut self, output: &mut [u8]) -> io::Result<usize> {
250	        if output.is_empty() { return Ok(0); }
251	        if self.left == 0 { self.left = self.sizes.pop_front().unwrap_or(output.len()); }
252	        let cap = self.left.min(output.len());
253	        let n = self.cursor.read(&mut output[..cap])?;
254	        self.left -= n;
255	        Ok(n)
256	    }
257	}
258	fn fragmented(data: &[u8], sizes: Vec<usize>, cap: usize, headers: bool) -> csv::Reader<Fragmented> {
259	    csv::ReaderBuilder::new().has_headers(headers).buffer_capacity(cap).from_reader(Fragmented::new(data, sizes))
260	}
