433	fn verify_index(data: &[u8], expected: Rows, offsets: &[u64], headers: bool, term: csv::Terminator, label: &str) {
434	    for cap in [1, 64] {
435	        let dir = PathBuf::from(std::env::var_os("CSV_BOM_SCRATCH").unwrap()).join(format!("{}-{}-{}", label, headers, cap));
436	        fs::create_dir_all(&dir).unwrap();
437	        let source = dir.join("records.csv");
438	        let index_path = dir.join("records.idx");
439	        fs::write(&source, data).unwrap();
440	        let fresh = || csv::ReaderBuilder::new().has_headers(headers).buffer_capacity(cap).terminator(term)
441	            .from_reader(File::open(&source).unwrap());
442	        let mut sequential = fresh();
443	        let mut decoded = Rows::new();
444	        let mut sequential_positions = Vec::new();
445	        if headers {
446	            let header = sequential.byte_headers().unwrap().clone();
447	            if !header.is_empty() {
448	                decoded.push(fields(&header));
449	                sequential_positions.push(header.position().unwrap().byte());
450	            }
451	        }
452	        let mut record = csv::ByteRecord::new();
453	        while sequential.read_byte_record(&mut record).unwrap() {
454	            decoded.push(fields(&record));
455	            sequential_positions.push(record.position().unwrap().byte());
456	        }
457	        assert_eq!(decoded, expected);
458	        let mut indexed = fresh();
459	        let mut output = File::create(&index_path).unwrap();
460	        csv_index::RandomAccessSimple::create(&mut indexed, &mut output).unwrap();
461	        drop(output);
462	        let mut index = csv_index::RandomAccessSimple::open(File::open(&index_path).unwrap()).unwrap();
463	        assert_eq!(index.len(), expected.len() as u64);
464	        for i in (0..expected.len()).rev().chain(0..expected.len()) {
465	            let position = index.get(i as u64).unwrap();
466	            let stored_byte = position.byte();
467	            indexed.seek(position).unwrap();
468	            let found = indexed.read_byte_record(&mut record).unwrap();
469	            assert!(found, "index entry {} at byte {}, expected byte {}, did not return a record", i, stored_byte, offsets[i]);
470	            assert_eq!(fields(&record), expected[i], "indexed fields differ from sequential fields at entry {}", i);
471	            assert_eq!(stored_byte, offsets[i]);
472	        }
473	        assert!(index.get(index.len()).is_err());
474	        let mut expected_encoding = Vec::new();
475	        for &offset in offsets { expected_encoding.extend_from_slice(&offset.to_be_bytes()); }
476	        expected_encoding.extend_from_slice(&(expected.len() as u64).to_be_bytes());
477	        assert_eq!(fs::read(&index_path).unwrap(), expected_encoding, "existing big-endian index format");
478	        assert_eq!(sequential_positions, offsets);
479	    }
480	}
