import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile

RUST = r'''
use std::{collections::VecDeque, fs::{self, File}, io::{self, Cursor, Read, SeekFrom}, path::PathBuf};
use csv_core::{ReadFieldResult as F, ReadRecordResult as R};

type Rows = Vec<Vec<Vec<u8>>>;
const MARKED: &[u8] = b"\xef\xbb\xbf\"name\",value\r\n\xe7\x94\xb2,7\r\n";
const BODY: &[u8] = b"\"name\",value\r\n\xe7\x94\xb2,7\r\n";
const INDEXED: &[u8] = b"\xef\xbb\xbfa,b\n\xef\xbb\xbfc,d\ne,\xef\xbb\xbff\n";

fn row(fields: &[&[u8]]) -> Vec<Vec<u8>> {
    fields.iter().map(|f| f.to_vec()).collect()
}
fn ordinary_rows() -> Rows {
    vec![row(&[b"name", b"value"]), row(&[b"\xe7\x94\xb2", b"7"])]
}
fn indexed_rows() -> Rows {
    vec![row(&[b"a", b"b"]), row(&[b"\xef\xbb\xbfc", b"d"]), row(&[b"e", b"\xef\xbb\xbff"])]
}
fn fields(record: &csv::ByteRecord) -> Vec<Vec<u8>> {
    record.iter().map(|f| f.to_vec()).collect()
}
fn partitions(n: usize) -> Vec<Vec<usize>> {
    let mut result = Vec::new();
    for prefix in [vec![], vec![1], vec![1, 1], vec![1, 2], vec![2, 1], vec![3]] {
        let mut remaining = n;
        let mut sizes = Vec::new();
        for size in prefix {
            let size = size.min(remaining);
            if size > 0 { sizes.push(size); remaining -= size; }
        }
        if remaining > 0 { sizes.push(remaining); }
        result.push(sizes);
    }
    result.push(vec![1; n]);
    result
}
fn capacities(profile: usize, turn: usize) -> (usize, usize) {
    match profile {
        0 => (64, 16),
        1 => (1, 1),
        2 => (if turn % 3 == 0 { 0 } else { 1 }, 1),
        3 => (1, if turn % 3 == 1 { 0 } else { 1 }),
        _ => (if turn % 4 < 2 { 0 } else { 1 }, if turn % 4 == 0 || turn % 4 == 2 { 0 } else { 1 }),
    }
}
fn core(nfa: bool, term: Option<u8>) -> csv_core::Reader {
    let mut builder = csv_core::ReaderBuilder::new();
    builder.nfa(nfa);
    if let Some(byte) = term { builder.terminator(csv_core::Terminator::Any(byte)); }
    builder.build()
}
fn field_rows(reader: &mut csv_core::Reader, data: &[u8], sizes: &[usize], profile: usize) -> Rows {
    assert_eq!(sizes.iter().sum::<usize>(), data.len());
    let (mut pos, mut boundary, mut chunk) = (0, 0, 0);
    let mut result = Rows::new();
    let mut current_row = Vec::new();
    let mut current_field = Vec::new();
    for turn in 0..10000 {
        if pos == boundary && chunk < sizes.len() { boundary += sizes[chunk]; chunk += 1; }
        let input = &data[pos..boundary];
        let supplied = input.len();
        let (cap, _) = capacities(profile, turn);
        let mut output = vec![0; cap];
        let (status, nin, nout) = reader.read_field(input, &mut output);
        assert!(nin <= supplied, "read_field counted previously received input: {} > {}", nin, supplied);
        assert!(nout <= cap, "read_field output count exceeds supplied space");
        pos += nin;
        current_field.extend_from_slice(&output[..nout]);
        match status {
            F::Field { record_end } => {
                current_row.push(std::mem::take(&mut current_field));
                if record_end { result.push(std::mem::take(&mut current_row)); }
            }
            F::End => {
                assert_eq!(supplied, 0, "End requires caller-supplied empty input");
                assert_eq!(pos, data.len(), "End before consuming the input");
                assert!(current_field.is_empty() && current_row.is_empty(), "unfinished data at End");
                return result;
            }
            F::InputEmpty | F::OutputFull => {}
        }
    }
    panic!("read_field did not finish after restoring buffer space");
}
fn record_rows(reader: &mut csv_core::Reader, data: &[u8], sizes: &[usize], profile: usize) -> Rows {
    assert_eq!(sizes.iter().sum::<usize>(), data.len());
    let (mut pos, mut boundary, mut chunk) = (0, 0, 0);
    let mut result = Rows::new();
    let mut bytes = Vec::new();
    let mut ends = Vec::new();
    for turn in 0..10000 {
        if pos == boundary && chunk < sizes.len() { boundary += sizes[chunk]; chunk += 1; }
        let input = &data[pos..boundary];
        let supplied = input.len();
        let (cap, end_cap) = capacities(profile, turn);
        let mut output = vec![0; cap];
        let mut positions = vec![0; end_cap];
        let (status, nin, nout, nend) = reader.read_record(input, &mut output, &mut positions);
        assert!(nin <= supplied, "read_record counted previously received input: {} > {}", nin, supplied);
        assert!(nout <= cap && nend <= end_cap, "invalid read_record return counts");
        pos += nin;
        bytes.extend_from_slice(&output[..nout]);
        for &end in &positions[..nend] {
            assert!(end >= ends.last().copied().unwrap_or(0), "field ends are not ordered");
            assert!(end <= bytes.len(), "field end includes bytes absent from decoded output");
            ends.push(end);
        }
        match status {
            R::Record => {
                assert!(!ends.is_empty(), "record without a field end");
                assert_eq!(ends.last().copied(), Some(bytes.len()));
                let mut previous = 0;
                let mut decoded = Vec::new();
                for &end in &ends { decoded.push(bytes[previous..end].to_vec()); previous = end; }
                result.push(decoded);
                bytes.clear();
                ends.clear();
            }
            R::End => {
                assert_eq!(supplied, 0, "End requires caller-supplied empty input");
                assert_eq!(pos, data.len(), "End before consuming the input");
                assert!(bytes.is_empty() && ends.is_empty(), "unfinished data at End");
                return result;
            }
            R::InputEmpty | R::OutputFull | R::OutputEndsFull => {}
        }
    }
    panic!("read_record did not finish after restoring buffer space");
}
fn check_core(data: &[u8], expected: Rows, term: Option<u8>) {
    for nfa in [false, true] {
        for sizes in partitions(data.len()) {
            for profile in 0..5 {
                assert_eq!(field_rows(&mut core(nfa, term), data, &sizes, profile), expected,
                    "field API: nfa={} chunks={:?} buffers={}", nfa, sizes, profile);
                assert_eq!(record_rows(&mut core(nfa, term), data, &sizes, profile), expected,
                    "record API: nfa={} chunks={:?} buffers={}", nfa, sizes, profile);
            }
        }
    }
}
#[test]
fn core_marked_and_unmarked_csv() {
    check_core(MARKED, ordinary_rows(), None);
    check_core(BODY, ordinary_rows(), None);
}
#[test]
fn core_empty_and_complete_marker_only() {
    check_core(b"", vec![], None);
    check_core(b"\xef\xbb\xbf", vec![], None);
}
#[test]
fn core_incomplete_and_mismatching_prefixes() {
    for (data, expected) in [
        (&b"\xef"[..], vec![row(&[b"\xef"])]),
        (&b"\xef\xbb"[..], vec![row(&[b"\xef\xbb"])]),
        (&b"\xefx,y\nok,y\n"[..], vec![row(&[b"\xefx", b"y"]), row(&[b"ok", b"y"])]),
        (&b"\xef\xbb,x\nok,y\n"[..], vec![row(&[b"\xef\xbb", b"x"]), row(&[b"ok", b"y"])]),
        (&b"\xef\xbbx,y\nok,y\n"[..], vec![row(&[b"\xef\xbbx", b"y"]), row(&[b"ok", b"y"])]),
        (&b"\xef\xbb\xbe,x\n"[..], vec![row(&[b"\xef\xbb\xbe", b"x"])]),
        (&b"\xee\xbb\xbf,x\n"[..], vec![row(&[b"\xee\xbb\xbf", b"x"])]),
    ] { check_core(data, expected, None); }
}
#[test]
fn core_marks_after_position_zero_remain_data() {
    check_core(b"\xef\xbb\xbf\xef\xbb\xbfq,x\n", vec![row(&[b"\xef\xbb\xbfq", b"x"])], None);
    check_core(b"\xef\xbb\xbfa,\xef\xbb\xbfz\r\n\xef\xbb\xbfb,c\r\n",
        vec![row(&[b"a", b"\xef\xbb\xbfz"]), row(&[b"\xef\xbb\xbfb", b"c"])], None);
    check_core(b"\n\xef\xbb\xbfa,b\n", vec![row(&[b"\xef\xbb\xbfa", b"b"])], None);
}
#[test]
fn core_existing_quoting_rules() {
    check_core(b"\xef\xbb\xbf\"a\"\"b\",\"c,d\"\r\n\"x\ny\",z\r\n",
        vec![row(&[b"a\"b", b"c,d"]), row(&[b"x\ny", b"z"])], None);
}
#[test]
fn core_custom_terminator_preserves_prefix_data() {
    check_core(b"\xef\xbbx\xbb", vec![row(&[b"\xef"]), row(&[b"x"])], Some(0xbb));
}
#[test]
fn core_marker_chunks_are_not_eof_or_empty_fields() {
    let marker = b"\xef\xbb\xbf";
    for nfa in [false, true] {
        for sizes in [vec![1, 1, 1], vec![1, 2], vec![2, 1], vec![3]] {
            let mut f = core(nfa, None);
            let mut r = core(nfa, None);
            let mut pos = 0;
            for size in sizes {
                let input = &marker[pos..pos + size];
                let (status, nin, nout) = f.read_field(input, &mut [0; 1]);
                assert_eq!(status, F::InputEmpty);
                assert_eq!((nin, nout), (size, 0));
                let (status, nin, nout, nend) = r.read_record(input, &mut [0; 1], &mut [0; 1]);
                assert_eq!(status, R::InputEmpty);
                assert_eq!((nin, nout, nend), (size, 0, 0));
                pos += size;
            }
            assert_eq!(field_rows(&mut f, BODY, &[BODY.len()], 1), ordinary_rows());
            assert_eq!(record_rows(&mut r, BODY, &[BODY.len()], 1), ordinary_rows());
        }
    }
}
#[test]
fn core_reset_discards_pending_prefix_and_reenables_detection() {
    for nfa in [false, true] {
        for prefix in [&b"\xef"[..], &b"\xef\xbb"[..]] {
            let mut f = core(nfa, None);
            let mut r = core(nfa, None);
            assert_eq!(f.read_field(prefix, &mut [0; 1]), (F::InputEmpty, prefix.len(), 0));
            assert_eq!(r.read_record(prefix, &mut [0; 1], &mut [0; 1]), (R::InputEmpty, prefix.len(), 0, 0));
            f.reset(); r.reset();
            assert_eq!(field_rows(&mut f, b"fresh,z\n", &[8], 1), vec![row(&[b"fresh", b"z"])]);
            assert_eq!(record_rows(&mut r, b"fresh,z\n", &[8], 1), vec![row(&[b"fresh", b"z"])]);
            for _ in 0..2 {
                f.reset(); r.reset();
                assert_eq!(field_rows(&mut f, MARKED, &vec![1; MARKED.len()], 4), ordinary_rows());
                assert_eq!(record_rows(&mut r, MARKED, &vec![1; MARKED.len()], 4), ordinary_rows());
            }
            f.reset(); r.reset();
            let _ = f.read_field(prefix, &mut [0; 1]);
            let _ = r.read_record(prefix, &mut [0; 1], &mut [0; 1]);
            let (_, nin, nout) = f.read_field(b"x", &mut []);
            assert!(nin <= 1); assert_eq!(nout, 0);
            let (_, nin, nout, nend) = r.read_record(b"x", &mut [], &mut []);
            assert!(nin <= 1); assert_eq!((nout, nend), (0, 0));
            f.reset(); r.reset();
            assert_eq!(field_rows(&mut f, MARKED, &[MARKED.len()], 1), ordinary_rows());
            assert_eq!(record_rows(&mut r, MARKED, &[MARKED.len()], 1), ordinary_rows());
        }
    }
}

struct Fragmented { cursor: Cursor<Vec<u8>>, sizes: VecDeque<usize>, left: usize }
impl Fragmented {
    fn new(data: &[u8], sizes: Vec<usize>) -> Self {
        Self { cursor: Cursor::new(data.to_vec()), sizes: sizes.into(), left: 0 }
    }
}
impl Read for Fragmented {
    fn read(&mut self, output: &mut [u8]) -> io::Result<usize> {
        if output.is_empty() { return Ok(0); }
        if self.left == 0 { self.left = self.sizes.pop_front().unwrap_or(output.len()); }
        let cap = self.left.min(output.len());
        let n = self.cursor.read(&mut output[..cap])?;
        self.left -= n;
        Ok(n)
    }
}
fn fragmented(data: &[u8], sizes: Vec<usize>, cap: usize, headers: bool) -> csv::Reader<Fragmented> {
    csv::ReaderBuilder::new().has_headers(headers).buffer_capacity(cap).from_reader(Fragmented::new(data, sizes))
}
#[derive(Debug, serde::Deserialize, PartialEq)]
struct Person { name: String, value: u32 }
#[test]
fn csv_headers_serde_records_and_original_byte_positions() {
    for sizes in partitions(MARKED.len()) {
        for cap in [1, 2, 3, 64] {
            let mut reader = fragmented(MARKED, sizes.clone(), cap, true);
            assert_eq!(reader.headers().unwrap(), &csv::StringRecord::from(vec!["name", "value"]));
            assert_eq!(reader.byte_headers().unwrap().position().unwrap().byte(), 0);
            let decoded: Vec<Person> = reader.deserialize().collect::<Result<_, _>>().unwrap();
            assert_eq!(decoded, vec![Person { name: "\u{7532}".to_owned(), value: 7 }]);
            let mut reader = fragmented(MARKED, sizes.clone(), cap, false);
            let mut rec = csv::ByteRecord::new();
            let mut decoded = Rows::new();
            let mut positions = Vec::new();
            while reader.read_byte_record(&mut rec).unwrap() {
                decoded.push(fields(&rec));
                let position = rec.position().unwrap();
                positions.push((position.byte(), position.line(), position.record()));
            }
            assert_eq!(decoded, ordinary_rows());
            // Existing CRLF parsing returns at CR. The following read consumes LF.
            // Position 16 includes the three BOM bytes; LF has not raised the line yet.
            assert_eq!(positions, vec![(0, 1, 0), (16, 1, 1)]);
            let mut reader = fragmented(MARKED, sizes.clone(), cap, false);
            let strings: Rows = reader.records().map(|r| r.unwrap().iter().map(|f| f.as_bytes().to_vec()).collect()).collect();
            assert_eq!(strings, ordinary_rows());
        }
    }
    let mut unmarked = fragmented(BODY, vec![1; BODY.len()], 1, false);
    let decoded: Rows = unmarked.byte_records().map(|r| fields(&r.unwrap())).collect();
    assert_eq!(decoded, ordinary_rows());
}
#[test]
fn csv_empty_and_marker_only_have_no_records() {
    for data in [&b""[..], &b"\xef\xbb\xbf"[..]] {
        for sizes in partitions(data.len()) {
            for cap in [1, 64] {
                for headers in [false, true] {
                    let mut reader = fragmented(data, sizes.clone(), cap, headers);
                    assert!(!reader.read_byte_record(&mut csv::ByteRecord::new()).unwrap());
                    assert!(!reader.read_byte_record(&mut csv::ByteRecord::new()).unwrap());
                    let mut reader = fragmented(data, sizes.clone(), cap, headers);
                    assert!(!reader.read_record(&mut csv::StringRecord::new()).unwrap());
                }
            }
        }
    }
}
fn utf8_error(error: &csv::Error) {
    match error.kind() {
        csv::ErrorKind::Utf8 { err, .. } => {
            assert_eq!(err.field(), 0);
            assert_eq!(err.valid_up_to(), 0);
        }
        other => panic!("expected UTF-8 error, received {:?}", other),
    }
    let position = error.position().expect("UTF-8 error position");
    assert_eq!((position.byte(), position.line(), position.record()), (0, 1, 0));
}
#[test]
fn csv_invalid_prefix_is_lossless_and_utf8_error_is_recoverable() {
    let data = b"\xef\xbb,x\nok,y\n";
    for sizes in partitions(data.len()) {
        for cap in [1, 2, 64] {
            let mut bytes = fragmented(data, sizes.clone(), cap, false);
            let mut record = csv::ByteRecord::new();
            assert!(bytes.read_byte_record(&mut record).unwrap());
            assert_eq!(fields(&record), row(&[b"\xef\xbb", b"x"]));
            assert_eq!(record.position().unwrap().byte(), 0);
            assert!(bytes.read_byte_record(&mut record).unwrap());
            assert_eq!(fields(&record), row(&[b"ok", b"y"]));
            assert_eq!(record.position().unwrap().byte(), 5);
            assert!(!bytes.read_byte_record(&mut record).unwrap());
            let mut strings = fragmented(data, sizes.clone(), cap, false);
            let mut record = csv::StringRecord::new();
            utf8_error(&strings.read_record(&mut record).unwrap_err());
            assert!(strings.read_record(&mut record).unwrap());
            assert_eq!(record, csv::StringRecord::from(vec!["ok", "y"]));
            let position = record.position().unwrap();
            assert_eq!((position.byte(), position.line(), position.record()), (5, 2, 1));
            assert!(!strings.read_record(&mut record).unwrap());
        }
    }
}
#[test]
fn csv_incomplete_prefix_at_eof_remains_raw_data() {
    for data in [&b"\xef"[..], &b"\xef\xbb"[..]] {
