            let mut bytes = fragmented(data, sizes.clone(), 1, false);
            let mut record = csv::ByteRecord::new();
            assert!(bytes.read_byte_record(&mut record).unwrap());
            assert_eq!(fields(&record), row(&[data]));
            assert!(!bytes.read_byte_record(&mut record).unwrap());
            let mut strings = fragmented(data, sizes, 1, false);
            let mut record = csv::StringRecord::new();
            utf8_error(&strings.read_record(&mut record).unwrap_err());
            assert!(!strings.read_record(&mut record).unwrap());
        }
    }
}
#[test]
fn csv_custom_terminator_record_positions() {
    let data = b"\xef\xbbx\xbb";
    for sizes in partitions(data.len()) {
        for cap in [1, 2, 64] {
            let mut reader = csv::ReaderBuilder::new().has_headers(false).buffer_capacity(cap)
                .terminator(csv::Terminator::Any(0xbb)).from_reader(Fragmented::new(data, sizes.clone()));
            let mut record = csv::ByteRecord::new();
            let mut decoded = Rows::new();
            let mut positions = Vec::new();
            while reader.read_byte_record(&mut record).unwrap() {
                decoded.push(fields(&record));
                positions.push(record.position().unwrap().byte());
            }
            assert_eq!(decoded, vec![row(&[b"\xef"]), row(&[b"x"])]);
            assert_eq!(positions, vec![0, 2], "chunks={:?}, buffer={}", sizes, cap);
        }
    }
}
fn cursor_reader(cap: usize, headers: bool) -> csv::Reader<Cursor<Vec<u8>>> {
    csv::ReaderBuilder::new().has_headers(headers).buffer_capacity(cap).from_reader(Cursor::new(INDEXED.to_vec()))
}
#[test]
fn csv_seek_preserves_later_marks_and_recognizes_byte_zero() {
    for cap in [1, 64] {
        for headers in [false, true] {
            let mut reader = cursor_reader(cap, headers);
            let mut record = csv::ByteRecord::new();
            while reader.read_byte_record(&mut record).unwrap() {}
            for i in [1, 2, 0, 1, 0] {
                let offset = [0, 7, 14][i];
                let mut position = csv::Position::new();
                position.set_byte(offset).set_record(i as u64);
                reader.seek(position).unwrap();
                assert!(reader.read_byte_record(&mut record).unwrap());
                assert_eq!(fields(&record), indexed_rows()[i]);
                assert_eq!(record.position().unwrap().byte(), offset);
            }
        }
    }
}
#[test]
fn csv_seek_raw_uses_actual_nonzero_address_for_data() {
    for cap in [1, 64] {
        for headers in [false, true] {
            for kind in 0..3 {
                let mut reader = cursor_reader(cap, headers);
                if kind == 2 {
                    let mut position = csv::Position::new(); position.set_byte(7);
                    reader.seek_raw(SeekFrom::Start(7), position).unwrap();
                }
                let from = match kind { 0 => SeekFrom::Start(7), 1 => SeekFrom::End(-14), _ => SeekFrom::Current(0) };
                reader.seek_raw(from, csv::Position::new()).unwrap();
                let mut record = csv::ByteRecord::new();
                assert!(reader.read_byte_record(&mut record).unwrap());
                assert_eq!(fields(&record), indexed_rows()[1], "seek_raw must not alter fields when position metadata differs");
            }
        }
    }
}
#[test]
fn csv_seek_raw_to_actual_zero_recognizes_marker() {
    for cap in [1, 64] {
        let mut reader = cursor_reader(cap, false);
        let mut metadata = csv::Position::new(); metadata.set_byte(7);
        reader.seek_raw(SeekFrom::Start(0), metadata).unwrap();
