}
fn verify_index(data: &[u8], expected: Rows, offsets: &[u64], headers: bool, term: csv::Terminator, label: &str) {
    for cap in [1, 64] {
        let dir = PathBuf::from(std::env::var_os("CSV_BOM_SCRATCH").unwrap()).join(format!("{}-{}-{}", label, headers, cap));
        fs::create_dir_all(&dir).unwrap();
        let source = dir.join("records.csv");
        let index_path = dir.join("records.idx");
        fs::write(&source, data).unwrap();
        let fresh = || csv::ReaderBuilder::new().has_headers(headers).buffer_capacity(cap).terminator(term)
            .from_reader(File::open(&source).unwrap());
        let mut sequential = fresh();
        let mut decoded = Rows::new();
        let mut sequential_positions = Vec::new();
        if headers {
