    fn would_block_headers_and_deserialize() {
        #[derive(Debug, PartialEq, serde::Deserialize)]
        struct Row {
            // Deliberately ordered differently from the header row, so that
            // positional (instead of name based) mapping would fail.
            pop: u64,
