    fn would_block_borrowed_iterator_recreate() {
        let data = "h1,h2\na,b\nc,d\n";
        let mut rdr = ReaderBuilder::new()
            .continue_on_would_block(true)
            .from_reader(Stutter::new(data.as_bytes(), 1));
