/// Stash the partially read record interrupted by a `WouldBlock` I/O
/// error, so that a subsequent read can resume it.
///
/// The field data (`outlen` bytes) and field end positions (`endlen`
/// entries) read so far are moved out of the caller's record, leaving it
/// empty. The record keeps the position of the start of the interrupted
/// record, which was assigned to it when the read began.
fn stash_pending(
    &mut self,
    record: &mut ByteRecord,
    outlen: usize,
    endlen: usize,
) {
    let pos = record.position().cloned();
    let (fields, ends) = record.as_parts();
    fields.truncate(outlen);
    ends.truncate(endlen);
    self.pending = Some(PendingRecord {
        pos,
        fields: std::mem::take(fields),
        ends: std::mem::take(ends),
    });
}

